  "claims": [
    {
      "id": "c:2388454981",
      "kind": "approach",
      "harm": "V2-only gives a false sense of security regarding anonymity and traffic inspection while making peer discovery harder for older v1 nodes.",
      "quote": "A V2-only option will: not hide the fact that one runs bitcoin node... but it will give the false impression that it does those two things. Further, it will make it more difficult for old nodes to find peers to connect to. Concept NACK because of that.",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:2381451594",
        "c:2440608399",
        "c:3555608000"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:3517995745",
      "settled_by_quote": "with this post I would like to withdraw my \"Concept NACK\" and leave it in your capable hands. Concept 0"
    },
    {
      "id": "r:2419071104",
      "kind": "approach",
      "harm": "The option and related changes are counterproductive, risk network partitions, and mislead users about node obfuscation.",
      "quote": "NACK. This pull request and related efforts are bad for bitcoin in lot of ways not just partition risk. We need to fix other things before trying to achieve this.",
      "blocking": true,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    },
    {
      "id": "c:5035178818",
      "kind": "approach",
      "harm": "Coupling v2onlyclearnet with listen=0 shrinks network inbound capacity and deprives the network of v2 listening slots, exacerbating strain on v1 nodes.",
      "quote": "I cannot express how strongly I disagree with forcing listen=0. It is an outright anti-feature to unnecessarily tie a security/privacy setting to providing resources to others",
      "blocking": true,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    },
    {
      "id": "c:5035178818",
      "kind": "correctness",
      "harm": "DNS seeds and static address databases do not set the v2 flag, preventing a cold-start node with v2only from finding any peers.",
      "quote": "Addresses learned via dnsseed right now as well as the static addr databases don't have the v2 flag. And so a node that has v2 as a requirement for its peer selection won't find any peers at all from a cold start and will just sit connected to nothing.",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:5279048438"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5036801852",
      "settled_by_quote": "proposed in #35766, I think it makes sense to change regardless of this PR."
    },
    {
      "id": "rc:3222147684",
      "kind": "safety",
      "harm": "Unresolved destination hostnames delegated to a proxy might be clearnet addresses and mistakenly connected via unencrypted v1 transport.",
      "quote": "When pszDest is unresolved because DNS is delegated to a name proxy, it might be better to treat it as possibly IPv4/IPv6 and block v1 under -v2onlyclearnet.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:4554588949",
        "rc:3310828084"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:4554588949",
      "settled_by_quote": "pushed an update addressing @w0xlt's comments."
    }
  ],
  "support": [
    {
      "id": "c:2379597880",
      "verdict": "Concept ACK",
      "reason": "Allows node runners who want BIP324 encryption benefits to have clearnet peers without leaking plaintext over occasional v1 fallback connections.",
      "substantive": true
    },
    {
      "id": "c:2388558223",
      "verdict": "Concept ACK",
      "reason": "Prevents passive spying, increases tampering costs, and increases the difficulty of detecting node operation via stateless packet inspection.",
      "substantive": true
    },
    {
      "id": "r:3369242392",
      "verdict": "Approach ACK",
      "reason": "Helps avoid cleartext transaction relay and prevents easy detection by stateless packet inspection, especially when paired with disabled inbound clearnet.",
      "substantive": true
    },
    {
      "id": "r:3378943773",
      "verdict": "Concept ACK",
      "reason": "Agrees with coupling to nolisten to prevent partition dangers and ensure safe operation.",
      "substantive": true
    },
    {
      "id": "c:3482378717",
      "verdict": "Concept ACK",
      "reason": "V2 deployment is high enough that providing an outbound-v2-only option is reasonable.",
      "substantive": true
    },
    {
      "id": "c:3485606391",
      "verdict": "Concept ACK",
      "reason": "Agrees with adding the option.",
      "substantive": false
    },
    {
      "id": "c:3486217821",
      "verdict": "Concept ACK",
      "reason": "Convinced that the benefits outweigh the implementation and maintenance costs.",
      "substantive": true
    },
    {
      "id": "c:4039758978",
      "verdict": "Concept ACK",
      "reason": "The project has communicated that v2 protects against passive observers and this option fulfills that goal.",
      "substantive": true
    },
    {
      "id": "r:4580909986",
      "verdict": "Concept ACK",
      "reason": "Supports the option and leans toward disallowing incoming connections to minimize worst-case eclipse risks on legacy nodes.",
      "substantive": true
    },
    {
      "id": "r:5171561924",
      "verdict": "Concept ACK",
      "reason": "Supports the feature, preferring Option B so node operators can continue offering inbound capacity.",
      "substantive": true
    }
  ],
  "notes": "There is a major open architectural disagreement regarding whether -v2onlyclearnet must force -listen=0 (Option A) or allow v2-only inbound connections (Option B), causing the PR to be postponed past v32.0. Additionally, 1440000bytes maintains an open concept NACK against introducing the option."
}
